// Generated by scripts/build-glossary-data.mjs from content-source/glossary. Do not edit by hand.
// [slug, name, one-line definition, category, written in this locale (1) or English fallback (0)], sorted by name.
export const GLOSSARY_INDEX = Object.freeze({"locale":"zh-Hans","terms":[["bitcoin","比特币（Bitcoin，BTC）","比特币是 2009 年上线的第一个去中心化加密货币，总量上限 2100 万枚，通过工作量证明挖矿维护网络，代号 BTC。","basics",1],["bitcoin-halving","比特币减半（Bitcoin Halving）","比特币减半是指每产出 21 万个区块（约四年）矿工的区块奖励自动减少一半的规则，2024 年 4 月减半后奖励降至 3.125 BTC。","basics",1],["spot-bitcoin-etf","比特币现货ETF（Spot bitcoin ETF）","比特币现货ETF是在证券交易所上市、由基金直接持有真实比特币的交易所交易基金，投资者通过证券账户买卖份额，就能获得跟踪比特币价格的敞口。","regulation",1],["coin-margined-futures","币本位合约（Coin-Margined Futures）","币本位合约是用 BTC、ETH 等加密货币本身作为保证金并结算盈亏的合约，也叫反向合约，盈亏以币计价，而不是以 USDT 计价。","derivatives",1],["coin-vs-token","币和代币的区别（Coin vs Token）","币（Coin）通常指一条区块链自己的原生资产，如 BTC、ETH；代币（Token）则是基于已有区块链的智能合约发行的资产，如以太坊上的 USDT。","basics",1],["mark-price","标记价格（Mark Price）","标记价格是交易所用来计算未实现盈亏和判断强平的参考价格，通常以多家现货交易所的指数价格为基础，比最新成交价更难被短时操纵。","derivatives",1],["volatility","波动率（Volatility）","波动率是衡量资产价格在一段时间内上下变动幅度的指标，波动率越高，价格涨跌越剧烈，加密货币通常远高于股票和外汇。","basics",1],["position-sizing","仓位管理（Position Sizing）","仓位管理是根据账户总资金、可承受的单笔亏损和止损距离，计算每笔交易应该开多大仓位的方法，目的是让任何一笔交易都不会重伤账户。","trading",1],["trading-volume","成交量（Trading Volume）","成交量是在一段时间内实际成交的资产数量或金额，例如 24 小时成交量，用来衡量一个币或一个市场的交易活跃程度。","trading",1],["open-interest","持仓量（Open Interest）","持仓量是某个合约市场中所有尚未平仓的合约总量，每一份多单都对应一份空单，它衡量的是有多少资金仍然留在市场里。","derivatives",1],["blockchain-network","充提币网络（链的选择）","充提币网络是指充币或提币时选择的区块链，例如 USDT 可以走 TRC20、ERC20 或 BEP20 等不同网络，发送方和接收方必须选择同一条链。","wallets-security",1],["initial-margin","初始保证金（Initial Margin）","初始保证金是开立一笔杠杆或合约仓位时必须冻结的最低资金，等于仓位价值除以杠杆倍数，杠杆越高，所需初始保证金越少。","derivatives",1],["proof-of-reserves","储备金证明（Proof of Reserves）","储备金证明（PoR）是交易所公开证明自己持有的用户资产储备至少等于用户存款总额的做法，通常结合默克尔树和链上地址来让用户自行核验。","wallets-security",1],["satoshi","聪（Satoshi，sats）","聪是比特币的最小单位，1 BTC 等于 1 亿聪，以比特币创始人中本聪命名，英文常写作 sats。","basics",1],["tokenized-stocks","代币化股票（Tokenized stocks）","代币化股票是把上市公司股票的价格和经济权益映射到区块链代币上的产品，通常由发行方托管真实股票并按1:1发行代币，可在交易所或链上交易。","tokenized-assets",1],["tokenized-gold","代币化黄金（Tokenized gold）","代币化黄金是由发行方在金库中托管实物黄金、并按固定比例在区块链上发行的代币，例如1枚PAXG或XAUT对应1金衡盎司黄金，价格跟随金价变动。","tokenized-assets",1],["tokenized-treasuries","代币化美债（Tokenized treasuries）","代币化美债是把美国短期国债或投资国债的货币市场基金份额以代币形式发行到区块链上的产品，持有者可以在链上获得接近国债利率的收益。","tokenized-assets",1],["token-unlock","代币解锁（Token Unlock）","代币解锁是指原本锁仓、不能交易的代币按预定时间表释放进入流通，常见于团队、投资人和生态基金的份额。","basics",1],["tokenomics","代币经济学（Tokenomics）","代币经济学是指一个代币的供应量、分配比例、解锁节奏、用途和销毁机制等设计，决定了代币未来的供需结构。","basics",1],["token-approval","代币授权（Token Approval）","代币授权是你在链上允许某个智能合约动用你钱包里指定代币的操作，授权额度决定合约最多能转走多少，常用于 DEX 交易和 DeFi 存款。","wallets-security",1],["token-burn","代币销毁（Token Burn）","代币销毁是把代币发送到无人掌握私钥的地址或由合约直接注销，使其永久退出流通，从而减少总供应量。","basics",1],["geo-restrictions","地区限制（Geo-restrictions）","地区限制是指交易所因法律、牌照或制裁要求，禁止或限制某些国家和地区的用户注册、交易特定产品或使用全部服务的规定。","regulation",1],["address-poisoning","地址投毒（Address Poisoning）","地址投毒是一种诈骗手法，骗子生成一个首尾字符与你常用地址相同的假地址，向你发送小额或零额转账，让它混进你的交易记录，等你复制错地址。","wallets-security",1],["phishing","钓鱼攻击（Phishing）","钓鱼攻击是指诈骗者冒充交易所、钱包或项目方，通过假网站、假邮件、假客服诱导你交出密码、验证码、助记词或签下恶意授权，从而盗取资产。","wallets-security",1],["order-book","订单簿（Order Book）","订单簿是交易所实时列出某个交易对所有未成交买单和卖单的列表，按价格排列，显示每个价位挂了多少数量。","trading",1],["time-in-force","订单有效期（GTC、IOC、FOK）","订单有效期（Time in Force）规定了一笔订单在未成交时保留多久以及如何处理未成交部分，常见选项有 GTC、IOC 和 FOK。","trading",1],["dollar-cost-averaging","定投（DCA）","定投（DCA）是按固定周期、用固定金额买入同一资产的策略，不去猜测高低点，借助分批买入摊平成本、降低一次性买在高位的风险。","trading",1],["hedging","对冲（Hedging）","对冲是建立一个与现有持仓方向相反或相关的仓位，用来抵消部分价格波动风险的做法，例如持有现货的同时开合约空单。","derivatives",1],["long-short-ratio","多空比（Long/Short Ratio）","多空比是交易所统计的持有多单用户（或多单持仓）与持有空单用户（或空单持仓）之间的比例，用来观察散户或大户在某个合约上的情绪偏向。","derivatives",1],["multisig-wallet","多签钱包（Multisig Wallet）","多签钱包是需要多把私钥中的若干把共同签名才能转出资产的钱包，例如“3 选 2”，常用于团队资金、DAO 金库和大额个人资产管理。","wallets-security",1],["layer-2","二层网络（Layer 2，L2）","二层网络（L2）是建立在一层区块链之上的扩容方案，在二层批量处理交易后把结果提交回主链，以更低的费用借用主链安全性。","basics",1],["fiat-on-ramp","法币入金通道（Fiat on-ramp）","法币入金通道是把美元、欧元、人民币等法定货币换成加密资产的渠道，例如银行转账、银行卡快捷买币、第三方支付和P2P（C2C）交易。","regulation",1],["anti-phishing-code","防钓鱼码（Anti-phishing Code）","防钓鱼码是你在交易所设置的一段自定义文字，之后平台发来的官方邮件里都会带上它，用来帮你分辨真假邮件，识别冒充交易所的钓鱼信息。","wallets-security",1],["non-custodial-wallet","非托管钱包（自托管钱包）","非托管钱包是由你自己保管私钥或助记词的钱包，资产的控制权完全在你手里，没有任何平台能替你冻结、挪用或找回。","wallets-security",1],["insurance-fund","风险保障基金（Insurance Fund）","风险保障基金是合约交易所设立的资金池，用来弥补被强平仓位以差于破产价格成交时产生的穿仓损失，避免盈利方的收益受到影响。","derivatives",1],["wrapped-token","封装代币（Wrapped Token）","封装代币是把一种资产按 1:1 比例在另一条链或另一种标准下表示出来的代币，例如 WBTC 让比特币能在以太坊上使用，WETH 把 ETH 变成 ERC20 格式。","defi",1],["leverage","杠杆（Leverage）","杠杆是用较少的保证金控制较大仓位的方式，例如 10 倍杠杆意味着 1,000 USDT 保证金可以开出价值 10,000 USDT 的仓位，盈亏同样按仓位价值计算。","derivatives",1],["margin-trading","杠杆交易（Margin Trading）","杠杆交易是用自己的资金作保证金，向交易所借入资金或币来放大买卖规模的交易方式，借款要付利息，亏损到一定程度会被强平。","derivatives",1],["copy-trading","跟单交易（Copy trading）","跟单交易是交易所提供的一种功能，让你选择一位公开交易记录的带单员，按设定的比例或金额自动复制他的开仓和平仓操作。","exchange-features",1],["proof-of-work","工作量证明（PoW）","工作量证明（PoW）是一种共识机制，矿工通过大量计算竞争求解哈希难题，最先找到答案的人获得出块权和奖励，比特币采用这种机制。","basics",1],["public-key","公钥（Public Key）","公钥是由私钥通过数学运算得出、可以公开的密钥，网络用它来验证交易签名是否由对应私钥签出，钱包地址也是由公钥进一步计算得来的。","wallets-security",1],["stock-perpetuals","股票永续合约（Stock perpetuals）","股票永续合约是跟踪某只股票或股票指数价格、没有到期日的衍生品合约，用USDT等稳定币作保证金，可以做多做空并使用杠杆，通过资金费率与标的价格保持一致。","tokenized-assets",1],["maker-taker-fees","挂单费与吃单费（Maker/Taker Fee）","挂单费与吃单费是交易所按订单角色收取的两档手续费：挂在订单簿上等待成交、提供流动性的一方付挂单费，立即与已有挂单成交的一方付吃单费。","trading",1],["synthetic-dollar","合成美元（Synthetic dollar）","合成美元是一种通过持有现货加密资产、同时在永续合约上开等额空单实现Delta中性，从而让价值稳定在约1美元的稳定币，Ethena的USDe是代表。","stablecoins",1],["slippage","滑点（Slippage）","滑点是指订单实际成交价格与下单时预期价格之间的差异，常发生在市价单、大额交易、流动性差或行情剧烈波动时。","trading",1],["active-addresses","活跃地址数（Active addresses）","活跃地址数是指在一定时间内（通常是一天）作为发送方或接收方参与过链上交易的不重复地址数量，常被用来粗略衡量一条区块链的使用热度。","onchain",1],["futures-basis","基差（Futures Basis）","基差是期货合约价格与现货价格之间的差额，期货高于现货叫升水，低于现货叫贴水，到期时交割合约的基差会收敛到接近零。","derivatives",1],["cryptocurrency","加密货币（Cryptocurrency）","加密货币是依靠密码学和区块链记账、无需银行等中心机构即可点对点转移的数字资产，比特币是第一个加密货币。","basics",1],["options","加密期权（Crypto Options）","加密期权是一种合约，买方支付权利金后，获得在到期日以约定行权价买入（看涨期权）或卖出（看跌期权）某种加密资产的权利，但没有义务。","derivatives",1],["crypto-wallet","加密钱包（Crypto Wallet）","加密钱包是用来保管私钥、查看余额并签名发送交易的工具，币本身记录在区块链上，钱包保管的是控制这些币的密钥。","wallets-security",1],["crypto-backed-stablecoin","加密资产抵押型稳定币（Crypto-backed stablecoin）","加密资产抵押型稳定币是用户把ETH等加密资产超额抵押进智能合约后铸造出来的稳定币，DAI是最典型的例子，抵押品不足时仓位会被清算。","stablecoins",1],["delivery-futures","交割合约（Delivery Futures）","交割合约是有固定到期日的期货合约，例如当周、次周、当季、次季合约，到期时按交割价格自动结算，不需要支付资金费率。","derivatives",1],["trading-pair","交易对（Trading Pair）","交易对是指两种资产相互报价、可以直接兑换的组合，如 BTC/USDT 表示用 USDT 买卖 BTC，价格表示 1 个 BTC 值多少 USDT。","trading",1],["transaction-hash","交易哈希（TxID）","交易哈希（TxID）是每笔链上交易独一无二的编号，由交易数据计算得出，用它可以在区块浏览器里查到这笔转账的状态、金额和确认数。","wallets-security",1],["exchange-netflow","交易所净流入/净流出（Exchange netflow）","交易所净流入/净流出是指一段时间内转入中心化交易所的某种加密资产数量减去从交易所转出的数量，用来观察资金是在涌向交易所还是离开交易所。","onchain",1],["node","节点（Node）","节点是运行区块链客户端软件、保存账本数据并按共识规则验证和转发交易与区块的计算机，全节点会独立校验每一个区块是否合法。","onchain",1],["whale","巨鲸（Whale）","巨鲸是指持有某种加密资产数量极大的个人或机构地址，他们的买卖或转账规模足以影响市场价格和情绪。","trading",1],["airdrop","空投（Airdrop）","空投是项目方免费向符合条件的钱包地址或用户发放代币的方式，常用于奖励早期用户、分散持币和推广项目。","basics",1],["fear-and-greed-index","恐惧与贪婪指数（Fear and Greed Index）","恐惧与贪婪指数是把价格波动、成交量、社交媒体热度、资金费率等数据综合成0到100分数的市场情绪指标，分数越低代表越恐惧，越高代表越贪婪。","onchain",1],["cross-chain-bridge","跨链桥（Cross-chain Bridge）","跨链桥是把资产或信息从一条区块链转移到另一条区块链的协议，常见方式是在源链锁定资产、在目标链铸造等量的映射代币。","defi",1],["cold-wallet","冷钱包（冷存储）","冷钱包是把私钥保存在不联网环境中的钱包或存储方式，例如硬件钱包和离线生成的纸钱包，主要用于长期、安全地存放大额加密资产。","wallets-security",1],["crypto-earn","理财/赚币（Crypto Earn）","理财（赚币）是交易所提供的加密资产收益产品，把你账户里的闲置币放进活期或定期产品中，由平台通过借贷、质押或其他方式产生收益并按约定发放。","exchange-features",1],["all-time-high","历史最高价（ATH）","历史最高价（ATH，All-Time High）是某个资产自上市交易以来曾达到的最高价格，创新高即价格突破这一纪录。","basics",1],["on-chain-analysis","链上分析（On-chain analysis）","链上分析是通过研究区块链上公开记录的转账、地址余额、交易所资金流向等数据，来判断市场参与者行为和资金动向的分析方法。","onchain",1],["liquidity","流动性（Liquidity）","流动性是指一个资产能否在不明显推动价格的情况下快速买入或卖出，流动性越好，买卖价差越窄、大额成交的滑点越小。","trading",1],["liquidity-pool","流动性池（Liquidity Pool）","流动性池是锁在智能合约里的一对或多种代币储备，交易者直接与池子兑换，存入资金的流动性提供者按份额获得手续费收入，是 DEX 运作的基础。","defi",1],["yield-farming","流动性挖矿（Yield Farming）","流动性挖矿是指把加密资产存入 DeFi 协议提供流动性或借贷，以赚取手续费、利息以及协议额外发放的代币奖励的做法。","defi",1],["liquid-staking","流动性质押（Liquid Staking）","流动性质押是把代币交给质押协议进行质押，同时获得一个可交易的凭证代币（如 stETH），让你在赚取质押奖励的同时仍能使用这部分资产。","defi",1],["circulating-supply","流通量（Circulating Supply）","流通量是指当前已在市场上自由流通、可以被交易的代币数量，不包括仍处于锁仓或尚未发行的部分。","basics",1],["travel-rule","旅行规则（Travel Rule）","旅行规则是FATF第16条建议对虚拟资产服务商的要求：在转账时收集并传递汇款方和收款方的身份信息，让资金和信息一起“旅行”。","regulation",1],["bid-ask-spread","买卖价差（Bid-Ask Spread）","买卖价差是订单簿上最高买价与最低卖价之间的差额，代表立即买入再立即卖出所要承担的隐性成本。","trading",1],["short-selling","卖空（Short Selling）","卖空是先借入或通过合约卖出自己并不持有的资产，等价格下跌后再买回归还或平仓，从下跌中赚取差价的交易方式。","derivatives",1],["no-kyc-exchange","免KYC交易所（No-KYC exchange）","免KYC交易所是指不要求用户提交身份证件即可注册、交易或在一定额度内提币的交易平台，包括部分中心化交易所和链上去中心化交易所（DEX）。","regulation",1],["demo-trading","模拟交易（Demo trading）","模拟交易是交易所用虚拟资金提供的练习环境，界面和行情与真实市场一致，你可以在不投入真钱的情况下熟悉下单、杠杆、止损和强平机制。","exchange-features",1],["mempool","内存池（Mempool）","内存池是区块链节点用来暂存已广播但尚未被打包进区块的交易的等待区，交易在这里排队，矿工或验证者通常优先打包手续费更高的交易。","onchain",1],["bull-market","牛市（Bull Market）","牛市是指加密货币或其他资产价格在较长时间内持续上涨、成交活跃、市场情绪普遍乐观的阶段，与之相对的是熊市。","basics",1],["rug-pull","跑路（Rug Pull）","Rug Pull（跑路、拉地毯）是指项目方在吸引投资者买入后，突然撤走流动性池中的资金、大量抛售手中代币或卷走资金，导致代币价格瞬间归零。","wallets-security",1],["futures-contract","期货合约（Futures Contract）","期货合约是约定在未来以特定价格买入或卖出某种资产的标准化协议，在加密货币交易所中通常不交割实物币，而是用保证金结算盈亏。","derivatives",1],["wallet-address","钱包地址（Wallet Address）","钱包地址是区块链上用于收款的一串字符，相当于你的收款账号，由公钥计算得出，可以公开给别人，但不同链的地址格式不同。","wallets-security",1],["liquidation","强平（Liquidation）","强平（俗称爆仓）是指杠杆或合约仓位的保证金因亏损低于维持保证金要求时，交易所系统自动强制平掉该仓位，以防亏损超过保证金。","derivatives",1],["liquidation-price","强平价（Liquidation Price）","强平价是标记价格达到后会触发仓位强制平仓的价格，由开仓价、杠杆倍数、维持保证金率以及保证金模式共同决定。","derivatives",1],["blockchain","区块链（Blockchain）","区块链是一种由众多节点共同维护、按时间顺序把交易打包成区块并用密码学串联起来的公开账本，写入后极难篡改。","basics",1],["block-explorer","区块浏览器（Block explorer）","区块浏览器是一种可以按交易哈希、钱包地址或区块高度查询区块链上公开记录的网站或工具，例如以太坊的Etherscan和波场的Tronscan。","onchain",1],["block-confirmations","区块确认数（Confirmations）","区块确认数是指一笔交易被打包进区块后，其后又新增了多少个区块，确认数越多，交易被回滚的可能性越小，交易所据此决定何时为你入账。","wallets-security",1],["dex","去中心化交易所（DEX）","去中心化交易所（DEX）是基于智能合约运行的交易平台，你直接用自己的钱包交易，不需要注册账户或把资产托管给平台，典型代表有 Uniswap 和 PancakeSwap。","defi",1],["cross-margin","全仓保证金（Cross Margin）","全仓保证金是一种保证金模式，账户内所有可用余额共同为全部全仓仓位提供保证金，抗波动能力更强，但一旦强平可能亏掉整个账户余额。","derivatives",1],["proof-of-stake","权益证明（PoS）","权益证明（PoS）是一种共识机制，验证者通过质押代币获得出块和验证资格，作恶会被罚没质押，以太坊自 2022 年起采用。","basics",1],["hot-wallet","热钱包（Hot Wallet）","热钱包是私钥存放在联网设备上的加密货币钱包，例如手机钱包和浏览器插件钱包，使用方便，但更容易受到网络攻击。","wallets-security",1],["pig-butchering-scam","杀猪盘","杀猪盘是一种长期设局的诈骗，骗子先通过交友、恋爱或“带单”建立信任，再引导你在虚假平台投资加密货币，等你投入越来越多后卷款消失。","wallets-security",1],["altcoin","山寨币（Altcoin）","山寨币是指比特币以外的所有加密货币，包括以太坊、Solana 等公链币，也包括各种应用代币和 Meme 币。","basics",1],["flash-loan","闪电贷（Flash Loan）","闪电贷是一种无需抵押的链上借款，借款和还款必须在同一笔交易内完成，如果交易结束时没有连本带息还清，整笔交易就会被撤销，就像没发生过一样。","defi",1],["instant-convert","闪兑（Convert）","闪兑是交易所提供的一键兑换功能，你输入要兑换的币种和数量，平台给出一个锁定几秒的报价，确认后立即按报价完成兑换，无需在订单簿上挂单。","exchange-features",1],["token-listing","上币（Token listing）","上币是指交易所正式开放某个代币的充值和交易，为它开设现货或合约交易对，让用户可以在平台上买卖，通常会提前发布上币公告和开盘时间。","exchange-features",1],["market-order","市价单（Market Order）","市价单是以当前市场上最优可得价格立即成交的订单，优点是成交快、几乎一定成交，缺点是无法控制成交价格。","trading",1],["market-capitalization","市值（Market Cap）","市值是一个加密货币的当前价格乘以流通量得到的总价值，用来比较不同币种的规模，英文为 Market Cap。","basics",1],["wash-trading","刷量（Wash Trading）","刷量是指同一方或串通的几方自己买卖自己的订单，制造虚假的成交量和活跃度，让一个币或一家交易所看起来比实际更热门。","trading",1],["dual-investment","双币投资（Dual investment）","双币投资是一种结构化理财产品：你选择目标价格和期限并获得较高的约定收益，到期时根据结算价与目标价的关系，用原币种或另一种币种连本带息结算。","exchange-features",1],["two-factor-authentication","双重验证（2FA）","双重验证（2FA）是在密码之外再加一道验证的登录与操作保护，常见形式有验证器 App 动态码、短信验证码和硬件安全密钥。","wallets-security",1],["private-key","私钥（Private Key）","私钥是一串只有持有人知道的随机数字，用来对交易进行数字签名，证明你有权动用某个地址里的资产，私钥泄露就等于资产失控。","wallets-security",1],["algorithmic-stablecoin","算法稳定币（Algorithmic stablecoin）","算法稳定币是主要依靠代码规则调节供应量、而不是靠足额现金或抵押品来维持1美元价格的稳定币，在信心崩溃时容易出现严重脱锚。","stablecoins",1],["hash-rate","算力（Hash rate）","算力是矿机或整个工作量证明网络每秒能完成的哈希计算次数，常用TH/s、EH/s表示，全网算力越高，攻击网络所需的成本通常越高。","onchain",1],["arbitrage","套利（Arbitrage）","套利是利用同一资产在不同市场、不同产品或不同时间点之间的价格差，同时低买高卖、尽量不承担方向风险来赚取差价的交易方式。","trading",1],["withdrawal-whitelist","提币白名单（Withdrawal Whitelist）","提币白名单是交易所的一项安全设置，开启后账户只能向你事先登记并验证过的地址提币，即使账户被盗，对方也难以把资产转到陌生地址。","wallets-security",1],["withdrawal-fee","提币手续费（Withdrawal fee）","提币手续费是你把加密资产从交易所转出到外部地址时，交易所收取的费用，通常按币种和网络收取固定数量，用于覆盖链上Gas费和平台的处理成本。","exchange-features",1],["unified-trading-account","统一账户（Unified trading account）","统一账户是交易所把现货、杠杆、合约和期权等交易放在同一个账户中的模式，账户里多种资产可以按折算率共同作为保证金，盈亏可以相互抵消。","exchange-features",1],["custodial-wallet","托管钱包（Custodial Wallet）","托管钱包是由交易所或其他第三方代为保管私钥的钱包，你通过账户密码登录使用，资产实际由平台控制，便捷但要承担平台风险。","wallets-security",1],["depeg","脱锚（Depeg）","脱锚是指稳定币或锚定类资产的市场价格明显偏离它承诺跟随的价值，例如本应等于1美元的稳定币跌到0.95美元或涨到1.03美元。","stablecoins",1],["mining","挖矿（Crypto Mining）","挖矿是在工作量证明区块链上用计算设备竞争打包区块、维护网络安全并获得新币奖励和手续费的过程。","basics",1],["fully-diluted-valuation","完全稀释估值（FDV）","完全稀释估值（FDV）是用当前价格乘以代币最大供应量（或总供应量）算出的估值，表示所有代币都流通后的理论市值。","basics",1],["grid-trading-bot","网格交易机器人（Grid trading bot）","网格交易机器人是在你设定的价格区间内按等距价位自动挂出一组买单和卖单的交易工具，价格每下跌一格就买入、每上涨一格就卖出，赚取震荡中的差价。","exchange-features",1],["maintenance-margin","维持保证金（Maintenance Margin）","维持保证金是持有合约仓位所需的最低保证金，当仓位的保证金余额（含未实现盈亏）跌到这个水平时，交易所会触发强制平仓。","derivatives",1],["unrealized-pnl","未实现盈亏（Unrealized PnL）","未实现盈亏是仓位尚未平仓时，按当前价格（合约中通常是标记价格）计算出的账面盈利或亏损，只有平仓后才变成已实现盈亏。","derivatives",1],["stablecoin","稳定币（Stablecoin）","稳定币是一种设计为与美元等法币或资产保持稳定兑换比例的加密货币，最常见的是 1 枚兑 1 美元的 USDT 和 USDC，是加密交易中的主要计价和结算工具。","stablecoins",1],["impermanent-loss","无常损失（Impermanent Loss）","无常损失是指你在 AMM 流动性池中提供流动性时，因两种代币价格比例变化，导致取回资产的价值低于单纯持有这些代币所造成的差额。","defi",1],["delisting","下架（Delisting）","下架是指交易所停止某个代币或交易对的交易服务，通常先发布公告、给出停止交易和停止提币的时间，之后用户只能在规定期限内把资产提走或兑换。","exchange-features",1],["spot-trading","现货交易（Spot Trading）","现货交易是以当前市场价格直接买卖加密货币并即时完成交割的交易方式，买入后你真正持有这个币。","trading",1],["real-world-assets","现实世界资产（RWA）","现实世界资产（RWA）是指被代币化后在区块链上发行和流通的链下资产，例如国债、货币市场基金、私人信贷、房地产、黄金和股票等。","tokenized-assets",1],["limit-order","限价单（Limit Order）","限价单是指定价格买入或卖出的订单，只在市场价格达到或优于你设定的价格时才成交，可能部分成交或一直不成交。","trading",1],["bear-market","熊市（Bear Market）","熊市是指加密货币或其他资产价格在较长时间内持续下跌、市场情绪悲观、成交量和关注度明显下降的阶段，与之相对的是牛市。","basics",1],["vasp","虚拟资产服务提供商（VASP）","VASP是“虚拟资产服务提供商”的缩写，指为他人提供加密资产兑换、转账、托管或发行相关服务的企业，例如中心化交易所和托管钱包服务商。","regulation",1],["short-squeeze","轧空（Short Squeeze）","轧空是指价格上涨迫使大量空头止损或被强平，他们的平仓买单又进一步推高价格，形成连锁反应、价格在短时间内急速拉升的现象。","derivatives",1],["validator","验证者（Validator）","验证者是权益证明区块链上质押代币、负责提议和验证新区块的节点运营者，正常工作获得奖励，违规会被罚没质押。","basics",1],["cbdc","央行数字货币（CBDC）","央行数字货币（CBDC）是由一个国家或地区的中央银行发行的数字形式法定货币，与现金一样是央行的直接负债，例如中国的数字人民币（e-CNY）。","stablecoins",1],["referral-code","邀请码（返佣）","邀请码是交易所发给用户或合作方的推荐编号，新用户注册时填写后，双方可能获得手续费返佣、注册奖励等，具体权益由交易所的推荐计划规定。","exchange-features",1],["layer-1","一层网络（Layer 1，L1）","一层网络（L1）是指自己负责共识、安全和交易结算的基础区块链，比如比特币、以太坊、Solana 和 BNB Chain。","basics",1],["trailing-stop","移动止损（Trailing Stop）","移动止损是一种会随价格朝有利方向移动而自动跟进的止损单，以固定比例或金额保持与最高价（或最低价）的距离，价格回撤到该距离时触发。","trading",1],["ethereum","以太坊（Ethereum，ETH）","以太坊是支持智能合约的开源区块链，原生币为 ETH，用于支付 Gas 费和质押，DeFi、NFT 和大量代币都运行在它上面。","basics",1],["risk-reward-ratio","盈亏比（Risk-Reward Ratio）","盈亏比是一笔交易计划中可能亏损的金额与可能盈利的金额之比，例如止损亏 100、止盈赚 300，就是 1:3 的盈亏比。","trading",1],["hardware-wallet","硬件钱包（Hardware Wallet）","硬件钱包是一种专门保管私钥的小型实体设备，私钥在设备内部生成并签名，从不传到电脑或手机上，是最常用的冷钱包形式。","wallets-security",1],["perp-dex","永续合约 DEX（Perp DEX）","永续合约 DEX（Perp DEX）是在链上提供永续合约交易的去中心化平台，你用自己的钱包存入保证金开多或开空，资金费率、强平等机制与中心化交易所类似。","defi",1],["perpetual-futures","永续合约（Perpetual Futures）","永续合约是一种没有到期日的期货合约，可以无限期持有，通过多空双方定期互付资金费率，让合约价格始终贴近现货价格。","derivatives",1],["oracle","预言机（Oracle）","预言机是把链下数据（如币价、汇率、体育比分）传送到区块链上供智能合约使用的服务，DeFi 借贷、衍生品和稳定币都依赖它获取价格。","defi",1],["restaking","再质押（Restaking）","再质押是把已经质押的 ETH 或流动性质押凭证，再次用于为其他网络或服务提供安全保障，以换取额外奖励，同时承担额外罚没风险的做法。","defi",1],["support-and-resistance","支撑位与阻力位（Support and Resistance）","支撑位是价格下跌时多次止跌反弹的价格区域，阻力位（也叫压力位）是价格上涨时多次受阻回落的区域，交易者用它们规划入场、止损和止盈。","trading",1],["stop-loss","止损单（Stop-Loss）","止损单是预先设定一个触发价，当价格不利地达到该价位时自动卖出（或平仓）以限制亏损的订单。","trading",1],["stop-limit-order","止损限价单（Stop-Limit Order）","止损限价单是包含触发价和限价两个价格的条件单，价格达到触发价后，系统以你设定的限价挂出一笔限价单。","trading",1],["take-profit","止盈单（Take-Profit）","止盈单是预先设定目标价，当价格朝有利方向达到该价位时自动卖出（或平仓）锁定利润的订单。","trading",1],["reduce-only-order","只减仓（Reduce-Only）","只减仓是合约下单时的一个选项，勾选后这笔订单只能减少或平掉现有仓位，绝不会开出新仓或让仓位反向。","derivatives",1],["post-only-order","只做挂单（Post-Only）","只做挂单（Post-Only）是一种限价单选项，保证订单只以挂单（Maker）身份进入订单簿，如果会立即成交为吃单就自动取消或调整。","trading",1],["index-price","指数价格（Index Price）","指数价格是交易所根据多家主流现货交易所的价格，按一定权重加权计算出的综合现货价格，用作标记价格和资金费率的基准。","derivatives",1],["governance-token","治理代币（Governance Token）","治理代币是赋予持有人对协议或 DAO 提案投票权的代币，例如 UNI、AAVE，持有越多投票权越大，但不一定代表能分享协议收入。","defi",1],["staking","质押（Staking）","质押是把权益证明（PoS）区块链的代币锁定，用来支持网络验证并获得奖励的做法，你可以自己运行验证节点，也可以通过交易所或质押服务参与。","defi",1],["smart-contract","智能合约（Smart Contract）","智能合约是部署在区块链上、满足预设条件就自动执行的程序代码，DeFi、NFT 和链上代币都依靠它运行。","basics",1],["centralized-exchange","中心化交易所（CEX）","中心化交易所（CEX）是由公司运营、托管用户资产并撮合买卖订单的加密货币交易平台，如币安、OKX、Bybit、Bitget。","trading",1],["isolated-margin","逐仓保证金（Isolated Margin）","逐仓保证金是一种保证金模式，每个仓位只使用单独分配给它的保证金，仓位被强平时最多亏掉这部分，不会动用账户里的其他资金。","derivatives",1],["seed-phrase","助记词（Seed Phrase）","助记词是由 12 或 24 个英文单词组成的钱包备份，可以推导出钱包里的全部私钥，谁拿到助记词，谁就能控制这个钱包里的所有资产。","wallets-security",1],["margin-call","追加保证金（Margin Call）","追加保证金是指仓位亏损使保证金接近维持要求时，交易所发出风险提醒，要求你补充保证金或减仓，否则仓位可能被强制平仓。","derivatives",1],["funding-rate","资金费率（Funding Rate）","资金费率是永续合约中多头和空头之间定期互相支付的费率，用来让永续合约价格贴近现货指数价格，正费率时多头付给空头。","derivatives",1],["funding-rate-arbitrage","资金费率套利（Funding Rate Arbitrage）","资金费率套利是买入现货、同时在永续合约开等量空单，保持方向中性，赚取正资金费率期间空头收到的资金费的策略。","derivatives",1],["sub-account","子账户（Sub-account）","子账户是在同一个交易所主账户下开设的独立交易账户，资产和仓位彼此隔离，可以分别用于不同策略、API机器人或资金用途，并由主账户统一管理。","exchange-features",1],["auto-deleveraging","自动减仓（ADL）","自动减仓（ADL）是合约交易所在强平仓位无法以足够好的价格平掉、风险保障基金又不足以弥补亏损时，按排名强制减少对手方盈利仓位的风控机制。","derivatives",1],["amm","自动做市商（AMM）","自动做市商（AMM）是一种用流动性池和数学公式自动给代币定价的交易机制，不需要买卖双方挂单撮合，是 Uniswap 等去中心化交易所的核心。","defi",1],["total-value-locked","总锁仓价值（TVL）","总锁仓价值（TVL）是指存放在某个 DeFi 协议或某条公链智能合约中的资产总价值，通常以美元计算，用来衡量协议规模和资金规模。","defi",1],["portfolio-margin","组合保证金（Portfolio Margin）","组合保证金是一种按整个投资组合的净风险计算保证金的模式，现货、合约、期权的仓位可以互相抵消风险，对冲良好的组合所需保证金更低。","derivatives",1],["last-price","最新价（Last Traded Price）","最新价是某个交易对在订单簿上最后一笔实际成交的价格，也是交易软件和K线图上默认显示的实时价格。","derivatives",1],["long-and-short","做多与做空（Long and Short）","做多是预期价格上涨而买入或开多单，价格上涨时盈利；做空是预期价格下跌而卖出或开空单，价格下跌时盈利，两者是交易的两个基本方向。","derivatives",1],["market-maker","做市商（Market Maker）","做市商是在订单簿上持续同时挂出买单和卖单、为市场提供流动性的交易者或机构，主要通过买卖价差和交易所的挂单返佣获利。","trading",1],["aml","AML（反洗钱）","AML是“反洗钱”（Anti-Money Laundering）的缩写，指金融机构和交易所为识别、阻止非法资金进入正规体系而建立的一整套监控、审查和报告制度。","regulation",1],["apr-vs-apy","APR 和 APY 的区别","APR 是不计复利的年化收益率，APY 是计入复利后的年化收益率；同一个利率下，复利频率越高，APY 就比 APR 高得越多。","defi",1],["dao","DAO（去中心化自治组织）","DAO（去中心化自治组织）是通过智能合约和代币投票来管理资金与决策的组织形式，成员按持有的治理代币对提案投票，结果由链上规则或多签执行。","defi",1],["defi-lending","DeFi 借贷","DeFi 借贷是通过智能合约进行的超额抵押借贷，存款人把资产存入资金池赚利息，借款人先存入抵押品再借出其他资产，抵押不足时会被自动清算。","defi",1],["defi","DeFi（去中心化金融）","DeFi（去中心化金融）是指运行在区块链智能合约上的金融服务，比如交易、借贷、质押和收益聚合，用户用自己的钱包直接参与，无需银行或交易所作为中介。","defi",1],["fomo","FOMO（错失恐惧）","FOMO（Fear of Missing Out）指害怕错过上涨行情而冲动买入的心理，在币圈常表现为追高和临时加仓。","basics",1],["fud","FUD（恐惧、不确定、怀疑）","FUD 是 Fear、Uncertainty、Doubt 的缩写，指在市场上传播的恐惧、不确定和怀疑情绪或消息，常引发恐慌性抛售。","basics",1],["gas-fee","Gas 费（Gas Fee）","Gas 费是在以太坊等区块链上发送交易或调用智能合约时支付给网络的手续费，用链的原生币结算，高低取决于操作复杂度和网络拥堵。","basics",1],["hodl","HODL（长期持有）","HODL 是币圈对“长期持有不卖出”的俗称，源自 2013 年论坛里把 hold 拼错的帖子，后来也被解释为 Hold On for Dear Life。","basics",1],["candlestick-chart","K线图（Candlestick Chart）","K线图是用一根根K线记录每个时间段开盘价、最高价、最低价和收盘价的价格图表，是加密货币交易软件中最常用的看盘方式。","trading",1],["kyc","KYC（了解你的客户）","KYC是“了解你的客户”（Know Your Customer）的缩写，指交易所等金融服务机构在开户或提高额度时核实用户真实身份的流程，通常需要证件和人脸识别。","regulation",1],["launchpad","Launchpad（新币首发认购）","Launchpad是交易所或链上平台为新项目举办的代币首发认购活动，用户在上线交易前用稳定币或平台币按固定价格认购新币，超额认购时按比例分配。","exchange-features",1],["launchpool","Launchpool（质押挖新币）","Launchpool是交易所推出的新币挖矿活动：你在活动期间把指定代币或稳定币锁定到资金池中，按你在池子里所占的份额每天领取即将上线的新代币。","exchange-features",1],["memecoin","Meme 币（Memecoin）","Meme 币是以网络梗、动物形象或社区文化为主题、通常没有明确实际用途的加密货币，价格主要由社区热度和投机驱动。","basics",1],["memo-tag","Memo / 标签（Destination Tag）","Memo（也叫标签、Tag）是部分区块链转账时附带的一段数字或文字，交易所靠它识别充值属于哪个用户，充值时漏填或填错就可能无法自动到账。","wallets-security",1],["mev","MEV（最大可提取价值）","MEV（最大可提取价值）是指区块生产者或搜索者通过调整、插入或排除区块中交易的顺序所能额外获得的利润，三明治攻击（夹子）是最常见的例子。","defi",1],["mica","MiCA（欧盟加密资产市场法规）","MiCA是欧盟的《加密资产市场法规》，为加密资产发行方、稳定币和加密资产服务提供商（CASP）建立统一的许可和监管规则，适用于全部成员国。","regulation",1],["nft","NFT（非同质化代币）","NFT（非同质化代币）是区块链上每一枚都独一无二、不可互换的代币，常用来代表数字艺术、游戏道具、会员资格或域名等资产的所有权记录。","defi",1],["oco-order","OCO 订单（二选一订单）","OCO 订单（One-Cancels-the-Other）是把两笔订单绑定在一起，其中一笔成交后另一笔自动撤销，常用于同时设置止盈和止损。","trading",1],["p2p-trading","P2P交易（C2C交易）","P2P交易（币圈常称C2C）是指用户之间在交易所提供的撮合平台上直接买卖加密资产，买方通过银行转账等方式付款给卖方，平台托管卖方的币作为担保。","exchange-features",1],["usdt-margined-futures","U本位合约（USDT-Margined Futures）","U本位合约是以 USDT 等稳定币作为保证金并结算盈亏的合约，也叫正向或线性合约，盈亏直接以 USDT 计算，是新手最常用的合约类型。","derivatives",1],["usdc","USDC（美元币）","USDC 是由 Circle 公司发行、与美元 1:1 挂钩的稳定币，储备主要为现金和短期美国国债，以储备披露较透明著称，在 DeFi 和合规场景中使用广泛。","stablecoins",1],["usdt","USDT（泰达币）","USDT（泰达币）是由 Tether 公司发行、设计为与美元 1:1 挂钩的稳定币，也是市值和交易量最大的稳定币之一，大多数交易所的现货和合约都以它计价。","stablecoins",1],["vip-tier","VIP等级（VIP fee tier）","VIP等级是交易所根据用户过去一段时间的交易量或资产余额划分的手续费档位，等级越高，挂单和吃单手续费率通常越低，还可能获得更高的提币额度等权益。","exchange-features",1]]});
